<script setup>
import { ref,watch } from 'vue';
import { Link } from '@inertiajs/vue3';
import ListingImage from '@/Components/Marketplace/ListingImage.vue';
import AdminListingPreview from './AdminListingPreview.vue';
const props=defineProps({ listings:Object });
const selected=ref(null);
watch(()=>props.listings,()=>selected.value=null);
function rowClick(event,item){if(event.target.closest('a,button,input,select,textarea'))return;selected.value=item;}
const money=item=>new Intl.NumberFormat('en-PH',{style:'currency',currency:item.currency || 'PHP'}).format(item.price);
</script>
<template><p class="table-hint">Select a listing to inspect its photos, details, owner and status.</p><div class="admin-listings-table"><table><thead><tr><th>Listing</th><th>Type</th><th>Price</th><th>Owner / provider</th><th>Status</th><th>Preview</th></tr></thead><tbody><tr v-for="item in listings.data" :key="item.id" @click="rowClick($event,item)"><td><div class="table-listing"><button type="button" class="table-photo" :aria-label="`Preview photos for ${item.title}`" aria-haspopup="dialog" @click="selected=item"><ListingImage :src="item.photos?.[0]" :alt="item.title" :service="item.service" :type="item.type"/></button><div><button type="button" class="table-title" aria-haspopup="dialog" @click="selected=item">{{ item.title }}</button><small>{{ item.location.city || item.location.address || 'Location not provided' }}</small></div></div></td><td>{{ item.type }}</td><td class="table-price">{{ money(item) }}<small>/ {{ item.priceUnit }}</small></td><td><Link v-if="item.adminOwner.id" :href="`/admin/users/${item.adminOwner.id}/listings?service=${item.service}`">{{ item.adminOwner.name }}</Link><span v-else>{{ item.adminOwner.name }}</span></td><td><span class="table-status" :class="{'is-active':item.status==='active'}">{{ item.sourceStatus }}</span></td><td><button type="button" class="table-inspect" :aria-label="`Inspect ${item.title}`" aria-haspopup="dialog" @click="selected=item">Inspect ↗</button></td></tr><tr v-if="!listings.data.length"><td colspan="6" class="table-empty">No listings found.</td></tr></tbody></table></div><nav v-if="listings.last_page>1" class="table-pagination" aria-label="Listing pages"><Link v-if="listings.prev_page_url" :href="listings.prev_page_url">Previous</Link><span>Page {{ listings.current_page }} of {{ listings.last_page }}</span><Link v-if="listings.next_page_url" :href="listings.next_page_url">Next</Link></nav><AdminListingPreview v-if="selected" :item="selected" :owner="selected.adminOwner" @close="selected=null"/></template>
<style scoped>
.table-hint{font-size:13px;color:#637b76;margin-bottom:20px}.admin-listings-table{overflow-x:auto;border:1px solid #dce7e4;border-radius:12px;background:white}.admin-listings-table table{width:100%;text-align:left;font-size:13px}.admin-listings-table th{padding:14px 18px;background:#f7faf8;font-size:11px;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}.admin-listings-table td{padding:16px 18px;border-top:1px solid #e5edeb;vertical-align:middle}.admin-listings-table tbody tr{cursor:pointer}.admin-listings-table tbody tr:hover{background:#f4faf7}.table-listing{display:flex;align-items:center;gap:12px;min-width:260px;max-width:420px}.table-photo{width:72px;height:58px;flex-shrink:0;border-radius:8px;overflow:hidden}.table-title{font-weight:700;text-align:left;line-height:1.5;color:#12675f;overflow-wrap:anywhere}.admin-listings-table small{display:block;color:#637b76;font-size:11px;margin-top:6px}.table-price{white-space:nowrap;font-variant-numeric:tabular-nums}.table-status{display:inline-block;background:#eff3f1;padding:5px 8px;border-radius:6px;text-transform:capitalize;font-size:11px}.table-status.is-active{background:#e0f4eb;color:#12675f}.table-inspect{border:1px solid #b7d8d0;border-radius:8px;min-height:44px;padding:10px 12px;font-weight:600;color:#12675f;white-space:nowrap}.table-empty{text-align:center;padding:40px!important}.table-pagination{display:flex;justify-content:center;gap:20px;margin-top:24px;font-size:13px}.admin-listings-table :is(a,button):focus-visible{outline:2px solid #137671;outline-offset:3px}
</style>
